const string Dir="Assets/Scenes/Oasis/CoastalTerrain";static CoastalPrefabFinish(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("CoastalPrefabFinish.request")||EditorApplication.isCompiling)return;try{File.Delete("CoastalPrefabFinish.request");}catch(IOException){return;}Run();}
static float Height(TerrainData data,Vector3 origin,Vector3 p)=>origin.y+data.GetInterpolatedHeight(Mathf.Clamp01((p.x-origin.x)/data.size.x),Mathf.Clamp01((p.z-origin.z)/data.size.z));
static void RemapUV(Mesh mesh){var uv=mesh.uv;if(uv.Any(v=>Mathf.Abs(v.x-.61f)<.0001f||Mathf.Abs(v.x-.60f)<.0001f))return;for(int i=0;i<uv.Length;i++){float old=uv[i].x;if(old<.54f)uv[i].x=Mathf.Lerp(.005f,.61f,Mathf.InverseLerp(.005f,.525f,old));else uv[i].x=Mathf.Lerp(.60f,.995f,Mathf.InverseLerp(.55f,.995f,old));}mesh.uv=uv;EditorUtility.SetDirty(mesh);}
static void Soften(Mesh mesh){var vertices=mesh.vertices;var indices=mesh.triangles;var keys=vertices.Select(p=>new Vector3Int(Mathf.RoundToInt(p.x*20),Mathf.RoundToInt(p.y*20),Mathf.RoundToInt(p.z*20))).ToArray();var sums=new Dictionary<Vector3Int,Vector3>();foreach(int id in indices){var key=keys[id];if(!sums.ContainsKey(key))sums[key]=Vector3.zero;}for(int i=0;i<indices.Length;i+=3){var normal=Vector3.Cross(vertices[indices[i+1]]-vertices[indices[i]],vertices[indices[i+2]]-vertices[indices[i]]);for(int j=0;j<3;j++)sums[keys[indices[i+j]]]+=normal;}var normals=mesh.normals;for(int i=0;i<normals.Length;i++)if(sums.TryGetValue(keys[i],out var sum))normals[i]=Vector3.Lerp(normals[i],sum.normalized,.55f).normalized;mesh.normals=normals;EditorUtility.SetDirty(mesh);}
static void Child(GameObject root,string name,Mesh mesh,Material mat){var g=new GameObject(name);g.transform.SetParent(root.transform,false);g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=mat;}
static void Run(){var log=new StringBuilder();try{Directory.CreateDirectory(Dir+"/Prefabs");var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var roots=scene.GetRootGameObjects();var root=roots.Single(g=>g.name=="Coastal Rocky Terrain");var terrain=root.GetComponentInChildren<Terrain>();var data=terrain.terrainData;var previous=UnityEngine.Object.Instantiate(data);string backup=Dir+"/Before Rounded Alignment.asset";if(!AssetDatabase.LoadAssetAtPath<TerrainData>(backup))AssetDatabase.CreateAsset(UnityEngine.Object.Instantiate(data),backup);
var origin=terrain.transform.position;var size=data.size;var mask=data.GetHoles(0,0,512,512);var baseData=AssetDatabase.LoadAssetAtPath<TerrainData>(backup);var h=baseData.GetHeights(0,0,513,513);var distance=new int[512,512];var queue=new Queue<Vector2Int>();for(int z=0;z<512;z++)for(int x=0;x<512;x++){if(!mask[z,x]||x==0||z==0||x==511||z==511){distance[z,x]=0;queue.Enqueue(new Vector2Int(x,z));}else distance[z,x]=10000;}while(queue.Count>0){var p=queue.Dequeue();foreach(var e in new[]{new Vector2Int(1,0),new Vector2Int(-1,0),new Vector2Int(0,1),new Vector2Int(0,-1)}){var n=p+e;if(n.x<0||n.y<0||n.x>=512||n.y>=512)continue;if(distance[n.y,n.x]<=distance[p.y,p.x]+1)continue;distance[n.y,n.x]=distance[p.y,p.x]+1;queue.Enqueue(n);}}
for(int pass=0;pass<3;pass++){var next=(float[,])h.Clone();for(int z=1;z<512;z++)for(int x=1;x<512;x++){if(!mask[Mathf.Min(z,511),Mathf.Min(x,511)])continue;float sum=h[z,x]*4,weight=4;for(int j=-1;j<=1;j++)for(int k=-1;k<=1;k++){if(j==0&&k==0||!mask[Mathf.Min(511,z+j),Mathf.Min(511,x+k)])continue;sum+=h[z+j,x+k];weight++;}next[z,x]=Mathf.Lerp(h[z,x],sum/weight,.55f);}h=next;}
var shore=roots.Single(g=>g.name=="Track Roads").GetComponentsInChildren<MeshFilter>(true).Single(f=>f.name=="Outer_MEsh");var probeObject=new GameObject("Temporary ground alignment probe"){hideFlags=HideFlags.HideAndDontSave};probeObject.transform.SetPositionAndRotation(shore.transform.position,shore.transform.rotation);probeObject.transform.localScale=shore.transform.lossyScale;var probe=probeObject.AddComponent<MeshCollider>();probe.sharedMesh=shore.sharedMesh;bool backface=Physics.queriesHitBackfaces;Physics.queriesHitBackfaces=true;int lowered=0;float spacing=Mathf.Min(size.x,size.z)/512;
for(int z=0;z<513;z++)for(int x=0;x<513;x++){int mx=Mathf.Min(x,511),mz=Mathf.Min(z,511);if(!mask[mz,mx])continue;float wx=origin.x+x/512f*size.x,wz=origin.z+z/512f*size.z;float ground=27.74f;if(probe.Raycast(new Ray(new Vector3(wx,140,wz),Vector3.down),out var hit,180)&&hit.point.y>23.5f)ground=hit.point.y+.075f;float edge=distance[mz,mx]*spacing;float rise=Mathf.Max(0,h[z,x]*size.y-ground-.6f);float blend=Mathf.SmoothStep(0,1,Mathf.InverseLerp(0,9,edge));float y=ground+rise*blend;if(y<h[z,x]*size.y-.15f)lowered++;h[z,x]=Mathf.Max(.01f,y/size.y);}Physics.queriesHitBackfaces=backface;UnityEngine.Object.DestroyImmediate(probeObject);data.SetHeights(0,0,h);terrain.Flush();EditorUtility.SetDirty(data);
string atlasPath=Dir+"/Details/Natural Pine and Woodland Shrubs.png";var importer=(TextureImporter)AssetImporter.GetAtPath(atlasPath);importer.alphaIsTransparency=true;importer.mipmapEnabled=true;importer.mipMapsPreserveCoverage=true;importer.alphaTestReferenceValue=.35f;importer.streamingMipmaps=true;importer.wrapMode=TextureWrapMode.Clamp;importer.filterMode=FilterMode.Trilinear;importer.anisoLevel=2;importer.maxTextureSize=2048;foreach(string platform in new[]{"Android","iPhone"})importer.SetPlatformTextureSettings(new TextureImporterPlatformSettings{name=platform,overridden=true,maxTextureSize=2048,format=TextureImporterFormat.ASTC_6x6,compressionQuality=85});importer.SaveAndReimport();var atlas=AssetDatabase.LoadAssetAtPath<Texture2D>(atlasPath);var pineMat=AssetDatabase.LoadAssetAtPath<Material>(Dir+"/Details/Shared mountain pine.mat");var shrubMat=AssetDatabase.LoadAssetAtPath<Material>(Dir+"/Details/Shared mountain shrub.mat");foreach(var material in new[]{pineMat,shrubMat}){material.SetTexture("_Atlas",atlas);material.SetTexture("_BaseMap",atlas);material.SetFloat("_Cutoff",.35f);EditorUtility.SetDirty(material);}
var seen=new HashSet<Mesh>();int rockMeshes=0,plantMeshes=0;foreach(var f in root.GetComponentsInChildren<MeshFilter>(true)){var mesh=f.sharedMesh;if(!mesh||!seen.Add(mesh))continue;bool pine=f.transform.parent&&f.transform.parent.name.StartsWith("Pine_");bool plants=pine||f.transform.parent&&f.transform.parent.name.StartsWith("Shrub_");var p=mesh.vertices;if(plants){int stride=f.name=="Detailed"?12:8;for(int start=0;start<p.Length;start+=stride){int count=Mathf.Min(stride,p.Length-start);var anchor=Vector3.zero;for(int j=0;j<count;j++)anchor+=f.transform.TransformPoint(p[start+j]);anchor/=count;float delta=Height(data,origin,anchor)-Height(previous,origin,anchor);for(int j=0;j<count;j++)p[start+j].y+=delta;}plantMeshes++;}else{for(int i=0;i<p.Length;i++){var world=f.transform.TransformPoint(p[i]);p[i].y+=Height(data,origin,world)-Height(previous,origin,world);}rockMeshes++;}mesh.vertices=p;mesh.RecalculateBounds();if(pine)RemapUV(mesh);if(!plants){mesh.RecalculateNormals();Soften(mesh);}EditorUtility.SetDirty(mesh);}UnityEngine.Object.DestroyImmediate(previous);
for(int i=0;i<3;i++){foreach(string kind in new[]{"Pine","Shrub"}){var near=AssetDatabase.LoadAssetAtPath<Mesh>(Dir+"/Details/"+kind+" "+i+".asset");var far=AssetDatabase.LoadAssetAtPath<Mesh>(Dir+"/Details/"+kind+" "+i+" distant.asset");if(kind=="Pine"){RemapUV(near);RemapUV(far);}var template=new GameObject("Natural Mountain "+kind+" "+i);Child(template,"Detailed",near,kind=="Pine"?pineMat:shrubMat);Child(template,"Distant",far,kind=="Pine"?pineMat:shrubMat);var lod=template.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.18f,new[]{template.transform.GetChild(0).GetComponent<Renderer>()}),new LOD(.018f,new[]{template.transform.GetChild(1).GetComponent<Renderer>()})});lod.RecalculateBounds();PrefabUtility.SaveAsPrefabAsset(template,Dir+"/Prefabs/Natural "+kind+" "+i+".prefab");UnityEngine.Object.DestroyImmediate(template);}}
if(PrefabUtility.IsPartOfPrefabInstance(root))PrefabUtility.UnpackPrefabInstance(root,PrefabUnpackMode.OutermostRoot,InteractionMode.AutomatedAction);int nested=0;foreach(var container in root.transform.Cast<Transform>().ToArray()){if(container.GetComponent<Terrain>()){PrefabUtility.SaveAsPrefabAssetAndConnect(container.gameObject,Dir+"/Prefabs/Editable Coastal Terrain.prefab",InteractionMode.AutomatedAction);nested++;continue;}foreach(var child in container.Cast<Transform>().ToArray()){foreach(var lod in child.GetComponentsInChildren<LODGroup>())lod.RecalculateBounds();string safe=child.name.Replace('(','_').Replace(')','_').Replace(',','_');PrefabUtility.SaveAsPrefabAssetAndConnect(child.gameObject,Dir+"/Prefabs/"+safe+".prefab",InteractionMode.AutomatedAction);nested++;}}
data.SetBaseMapDirty();terrain.Flush();AssetDatabase.SaveAssets();PrefabUtility.SaveAsPrefabAssetAndConnect(root,Dir+"/Coastal Rocky Terrain.prefab",InteractionMode.AutomatedAction);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);capture.Invoke(null,new object[]{scene,new Vector3(813,31,150),new Vector3(819,35,350),"Final-Natural-Prefab-Road-Level"});capture.Invoke(null,new object[]{scene,new Vector3(365,130,680),new Vector3(333,28,568),"Final-Rounded-Terrain-Corner"});log.AppendLine("SUCCESS softened and ground-aligned Terrain vertices="+lowered+"; grounded plant batches="+plantMeshes+"; softened rock batches="+rockMeshes+"; new natural pine/shrub atlas; 6 individual plant template prefabs with near/distant LOD; placed detail sectors and terrain nested prefab instances="+nested+"; shared materials and spatial batching retained; scene/master prefab saved.");}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/CoastalPrefabFinishReport.txt",log.ToString());}}
